        const auto& seg1 = segments[i];
        const auto& seg2 = segments[j];

        // Orientation function to determine if point is collinear, clockwise, or counter-clockwise
        auto orientation = [](const std::Point2d& p, const std::Point2d& q, const std::Point2d& r) {
            std::double_t val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
            if (std::abs(val) < 1e-10) return 0;  // collinear
            return (val > 0) ? 1 : 2;             // clockwise or counter-clockwise
        };

        // Check if segments intersect
        auto onSegment = [](const std::Point2d& p, const std::Point2d& q, const std::Point2d& r) {
            return (std::min(p.x, q.x) <= r.x && r.x <= std::max(p.x, q.x) &&
                    std::min(p.y, q.y) <= r.y && r.y <= std::max(p.y, q.y));
        };

        // Check general case (non-parallel, non-collinear)
        auto o1 = orientation(seg1.p1, seg1.p2, seg2.p1);
        auto o2 = orientation(seg1.p1, seg1.p2, seg2.p2);
        auto o3 = orientation(seg2.p1, seg2.p2, seg1.p1);
        auto o4 = orientation(seg2.p1, seg2.p2, seg1.p2);

        if (o1 != o2 && o3 != o4) {
